(()=>{
'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=(s)=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const I=(name)=>ICONS[name]||'';
const repos=[
 {id:'open-folio',name:'OpenFolio',path:'demo-user / open-folio',description:'工程记录的阅读工作台，让规格、变更与原型保持连接。',specs:6,changes:3,prototypes:3,updated:'刚刚',favorite:true,ready:true,symbol:'O'},
 {id:'spec-trail',name:'SpecTrail',path:'demo-user / spec-trail',description:'从需求到交付，让每一次变更都有迹可循。',specs:8,changes:2,prototypes:1,updated:'25 分钟前',favorite:true,ready:true,symbol:'S'},
 {id:'component-lab',name:'Component Lab',path:'demo-team / component-lab',description:'共享组件、设计规范与交互模式的实验空间。',specs:4,changes:1,prototypes:2,updated:'2 小时前',favorite:false,ready:true,symbol:'C'},
 {id:'docs-kit',name:'Docs Kit',path:'demo-team / docs-kit',description:'团队文档与工程知识的统一入口。',specs:0,changes:0,prototypes:0,updated:'昨天',favorite:false,ready:false,symbol:'D'},
];
const documents=[
 {id:'overview',title:'工作台与仓库发现',group:'产品能力'},
 {id:'identity',title:'身份与访问权限',group:'产品能力'},
 {id:'reading',title:'工程记录阅读',group:'产品能力'},
 {id:'previews',title:'原型与公开分享',group:'产品能力'},
 {id:'theme',title:'共享组件与主题',group:'设计与实现'},
 {id:'runtime',title:'构建与运行',group:'设计与实现'},
];
const changes=[
 {id:'blue-glass',name:'工作台视觉与阅读体验',stage:'待验收',tone:'orange',branch:'change/workbench-refresh',tasks:'4 / 4',time:'10 分钟前',active:true,description:'精简工作台信息层级，统一阅读区域，并为导航和浮层加入克制的玻璃质感。'},
 {id:'prototype-entry',name:'原型总览与设备预览',stage:'实现中',tone:'',branch:'change/prototype-browser',tasks:'2 / 4',time:'1 小时前',active:true,description:'在同一个原型入口切换桌面、平板和手机，保持版本与页面上下文。'},
 {id:'reading-links',name:'阅读位置与分享链接',stage:'方案中',tone:'neutral',branch:'change/reading-links',tasks:'0 / 3',time:'3 小时前',active:true,description:'用稳定的阅读位置链接，让协作者直接到达同一份工程记录。'},
 {id:'identity-switch',name:'浏览器多身份切换',stage:'已归档',tone:'green',branch:'develop',tasks:'5 / 5',time:'10 月 16 日',active:false,description:'在一个浏览器里切换已记住的身份，保留各自独立的仓库和阅读上下文。'},
 {id:'component-theme',name:'共享组件与主题规范',stage:'已归档',tone:'green',branch:'develop',tasks:'3 / 3',time:'10 月 14 日',active:false,description:'统一基础组件的交互、语义颜色和键盘状态，便于主应用与原型复用。'},
 {id:'source-trace',name:'记录来源与版本追溯',stage:'已归档',tone:'green',branch:'develop',tasks:'4 / 4',time:'10 月 12 日',active:false,description:'阅读时可按需检查分支、提交和数据来源，保持正文与快照一致。'},
];
const state={repo:'open-folio',filter:'all',query:'',view:'grid',changeFilter:'active',changeQuery:'',doc:'overview',theme:'light',device:'pc-web',refreshing:false,lastUpdated:'刚刚',detailTab:'overview'};
const titles={home:'我的仓库',specs:'Specs',changes:'Changes',prototypes:'原型',settings:'偏好设置'};
const navItems=[['home','House','我的仓库'],['specs','BookOpen','Specs'],['changes','GitPullRequest','Changes'],['prototypes','PanelsTopLeft','原型']];
function route(){const value=location.hash.replace(/^#\/?/,'')||document.body.dataset.previewRoute||'home';const [path,query='']=value.split('?');const params=new URLSearchParams(query);if(params.has('repo')&&repos.some(r=>r.id===params.get('repo')&&r.ready))state.repo=params.get('repo');if(params.has('doc')&&documents.some(d=>d.id===params.get('doc')))state.doc=params.get('doc');return Object.hasOwn(titles,path)?path:'home';}
function go(page,params={}){const hash='#/'+page+(Object.keys(params).length?'?'+new URLSearchParams(params):'');if(location.hash===hash)render();else location.hash=hash;}
const href=(page,params={})=>'#/'+page+(Object.keys(params).length?'?'+new URLSearchParams(params):'');
const currentRepo=()=>repos.find(r=>r.id===state.repo)||repos[0];
const badge=(label,tone='',dot=false)=>`<span class="pill ${tone}">${dot?'<i class="dot"></i>':''}${esc(label)}</span>`;
const button=(text,action,icon='',kind='')=>`<button class="btn ${kind}" data-action="${action}">${icon?I(icon):''}${text}</button>`;
function mark(repo){return `<span class="project-mark ${repo.id==='open-folio'?'':'gray'}">${repo.id==='open-folio'?`<img src="${BRAND}" alt="">`:repo.symbol}</span>`;}
function toast(message){clearTimeout(toast.timer);$('#toast').innerHTML=I('CheckCircle2')+esc(message);$('#toast').classList.add('visible');toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),3000);}
function navigation(page,mobile=false){return navItems.map(([id,icon,label])=>`<a href="${href(id)}" class="${mobile?'':'nav-link'}" aria-label="${label}" ${page===id?'aria-current="page"':''}>${I(icon)}<span>${mobile&&id==='home'?'仓库':label}</span>${!mobile&&id==='changes'?'<span class="nav-count">3</span>':''}</a>`).join('');}
function render(){const page=route(),repo=currentRepo();document.title=`${titles[page]} · OpenFolio 原型`;document.documentElement.dataset.theme=state.theme;
 $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><a href="#/home" class="brand" aria-label="OpenFolio 首页"><img src="${BRAND}" alt=""><span>OpenFolio</span></a><button class="workspace-picker" data-action="pick-repo" aria-label="切换项目"><span class="workspace-emblem">${I('FolderGit2')}</span><span class="stack"><strong>${page==='home'||page==='settings'?'个人工作台':repo.name}</strong><span class="muted">${page==='home'||page==='settings'?'demo-user 的空间':'当前项目'}</span></span>${I('ChevronsUpDown')}</button><p class="nav-label">工作空间</p><nav class="main-nav" aria-label="模块导航">${navigation(page)}</nav><div class="favorites-nav"><p class="nav-label">已收藏</p>${repos.filter(r=>r.favorite).map(r=>`<a class="repo-nav" href="${href('specs',{repo:r.id,doc:'overview'})}"><i></i><span>${r.name}</span></a>`).join('')}</div><div class="sidebar-foot"><a class="side-action" href="#/settings">${I('Settings2')}<span>偏好设置</span></a><button class="side-action" data-action="help">${I('CircleHelp')}<span>使用帮助</span></button><div class="demo-note">${I('Info')}<span>交互原型 · 示例数据</span></div></div></aside><div class="main-wrap"><header class="topbar"><div class="breadcrumb"><a href="#/home" class="crumb-project">${page==='home'||page==='settings'?'个人工作台':repo.name}</a>${I('ChevronRight')}<span>${titles[page]}</span></div><div class="header-actions"><button class="search-launch" data-action="search" aria-label="全局搜索，快捷键 Command K">${I('Search')}<span>搜索工作台</span><kbd>⌘ K</kbd></button><button class="icon-btn ${state.refreshing?'spin':''}" data-action="refresh" aria-label="刷新工作台" ${state.refreshing?'disabled':''}>${I('RefreshCw')}</button><button class="icon-btn" data-action="theme" aria-label="切换为${state.theme==='light'?'深色':'浅色'}主题">${I(state.theme==='light'?'Moon':'Sun')}</button><button class="avatar" data-action="account" aria-label="查看示例身份 demo-user">D</button></div></header><main class="content ${page==='specs'?'reading-content':''}" id="main">${({home:home,specs:specs,changes:changePage,prototypes:prototypes,settings:settings})[page]()}</main></div></div><nav class="mobile-nav" aria-label="移动模块导航">${navigation(page,true)}</nav>`;
 if(page==='home')updateCards();if(page==='changes')updateChanges();
}
function heading(title,subtitle,actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`;}
function footer(){return `<footer class="page-footer"><span class="row">${I('CheckCheck')}已同步 · ${state.lastUpdated}<span>· 示例数据</span></span><button class="text-button small" data-action="source">${I('GitBranch')}GitHub · develop${I('ChevronRight')}</button></footer>`;}
function home(){return `${heading('我的仓库','每个项目的进展，都有清晰的入口。',button('检查仓库','add-repo','Plus','primary'))}<div class="section-label">${I('Clock3')}继续阅读</div><section class="resume-card" aria-label="继续阅读最近访问的记录"><div class="resume-main"><div class="resume-project">${mark(repos[0])}<div><strong>OpenFolio</strong><div class="muted">最近访问 · Specs</div></div></div><h2>工作台与仓库发现</h2><p>连接自己的身份，找到项目当前的规格与交付。</p><div class="resume-actions"><a class="btn primary" href="${href('specs',{repo:'open-folio',doc:'overview'})}">继续阅读${I('ArrowRight')}</a><a class="btn quiet" href="${href('changes',{repo:'open-folio'})}">查看变更${I('ArrowUpRight')}</a></div></div><div class="recent-activity"><h3>最近动态</h3><div class="activity-line"><i></i><div><a href="#/changes" data-open-change="blue-glass">工作台视觉与阅读体验</a><div class="activity-type">Change 已进入验收</div></div><time>10 分钟前</time></div><div class="activity-line"><i></i><div><a href="#/prototypes">新增原型设备预览</a><div class="activity-type">桌面、iPad 与手机</div></div><time>1 小时前</time></div><div class="activity-line"><i></i><div><a href="${href('specs',{doc:'identity'})}">身份与访问权限</a><div class="activity-type">Spec 内容已更新</div></div><time>昨天</time></div></div></section><div class="toolbar"><div class="tabs" role="tablist" aria-label="仓库筛选">${[['all','全部仓库',repos.length],['favorites','已收藏',repos.filter(r=>r.favorite).length],['attention','需关注',repos.filter(r=>!r.ready).length]].map(([id,label,n])=>`<button class="tab" role="tab" id="filter-${id}" aria-controls="repo-results" aria-selected="${state.filter===id}" data-filter="${id}">${label}<span class="tab-count">${n}</span></button>`).join('')}</div><div class="toolbar-right"><label class="input-wrap">${I('Search')}<span class="sr-only">搜索仓库</span><input id="repo-search" type="search" placeholder="搜索仓库…" value="${esc(state.query)}" autocomplete="off"></label><div class="view-toggle" role="group" aria-label="仓库显示方式"><button data-view="grid" aria-label="卡片视图" aria-pressed="${state.view==='grid'}">${I('LayoutGrid')}</button><button data-view="list" aria-label="列表视图" aria-pressed="${state.view==='list'}">${I('List')}</button></div></div></div><div id="repo-results" role="tabpanel" aria-labelledby="filter-${state.filter}" class="repo-grid ${state.view==='list'?'repository-list':''}"></div>${footer()}`;}
function updateCards(){const root=$('#repo-results');if(!root)return;const list=repos.filter(r=>(state.filter!=='favorites'||r.favorite)&&(state.filter!=='attention'||!r.ready)&&(r.name+' '+r.path+' '+r.description).toLowerCase().includes(state.query.toLowerCase()));root.innerHTML=list.length?list.map(r=>`<article class="repo-card"><div class="repo-top">${mark(r)}<button class="star-button" data-star="${r.id}" aria-label="${r.favorite?'取消收藏':'收藏'} ${r.name}" aria-pressed="${r.favorite}">${I('Star')}</button></div><div class="repo-card-main"><div class="repo-title-row"><h3><a href="${r.ready?href('specs',{repo:r.id,doc:'overview'}):'#'}" ${!r.ready?'data-action="setup"':''}>${r.name}</a></h3>${r.ready?'':badge('待接入','orange',true)}</div><div class="repo-path mono">${r.path}</div><p class="repo-description">${r.description}</p></div><div class="repo-stats">${r.ready?`<a href="${href('specs',{repo:r.id})}">${I('BookOpen')}<b>${r.specs}</b> Specs</a><a href="${href('changes',{repo:r.id})}">${I('GitPullRequest')}<b>${r.changes}</b> Changes</a><a href="${href('prototypes',{repo:r.id})}">${I('PanelsTopLeft')}<b>${r.prototypes}</b> 原型</a>`:`<button class="text-button" data-action="setup">查看接入方式${I('ArrowUpRight')}</button>`}<time>${r.updated}</time></div></article>`).join(''):`<div class="empty">${I('Search')}<h3>${state.query?'没有匹配的仓库':'还没有收藏的仓库'}</h3><p>${state.query?'试试仓库名、命名空间，或换一个关键词。':'点击仓库卡片右上角的星标，就能在这里找到它。'}</p><button class="btn" data-action="reset-filter">显示全部仓库</button></div>`;}
function repoSelect(){return `<label><span class="sr-only">当前项目</span><select class="repo-select" data-repo-select>${repos.filter(r=>r.ready).map(r=>`<option value="${r.id}" ${r.id===state.repo?'selected':''}>${r.name}</option>`).join('')}</select></label>`;}
const articleBodies={
 overview:`<p class="lead">OpenFolio 将仓库中的 Specs、Changes 与原型集中在同一处，让成员从项目当前状态出发，连续阅读工程记录。</p><h2>连接与发现</h2><p>使用自己的 GitHub 身份连接工作台。连接后，系统会发现已接入 SpecTrail 的仓库，并保留你最近访问的项目与阅读位置。</p><div class="info-note">${I('Info')}<span>仓库权限始终跟随当前身份。分享阅读位置时，协作者使用自己的凭据访问。</span></div><h2>一个项目，三个阅读入口</h2><table><thead><tr><th>入口</th><th>回答的问题</th></tr></thead><tbody><tr><td><strong>Specs</strong></td><td>当前已经实现的能力是什么？</td></tr><tr><td><strong>Changes</strong></td><td>正在推进哪些变更，进展到哪里？</td></tr><tr><td><strong>原型</strong></td><td>方案实际看起来、操作起来是什么样？</td></tr></tbody></table><h2>保持阅读连续</h2><p>切换项目时保留当前模块；重新打开工作台时，回到最近访问的位置。正文优先显示最近的有效快照，刷新失败时保留已读内容，并提供明确的恢复入口。</p><ul><li>通过全局搜索快速找到项目、规格和变更。</li><li>来源信息按需展开，正文区域专注阅读。</li><li>复制阅读链接，让协作者直接到达同一位置。</li></ul>`,
 identity:`<p class="lead">每个身份拥有独立的工作台上下文。仓库发现、阅读权限与设备会话都绑定当前凭据。</p><h2>同一个浏览器，多种身份</h2><p>已记住的身份可以直接切换。不同凭据的仓库与阅读上下文分别保存；显示名称用于区分身份，不参与权限判断。</p><div class="info-note">${I('ShieldCheck')}<span>原型只使用示例身份，不收集真实 token，也不连接 GitHub。</span></div><h2>访问与退出</h2><p>每次读取工程记录，都检查当前身份与仓库的访问关系。凭据失效或权限被撤销后，提供重新连接入口。</p><ul><li>移除当前浏览器中的身份，不会删除工作台内容。</li><li>退出设备时，同时取消该设备记住的授权。</li><li>分享链接只包含阅读位置，不携带访问凭据。</li></ul>`,
 reading:`<p class="lead">围绕当前记录组织目录、正文和相关变更，让阅读过程连贯，也让来源可以核对。</p><h2>阅读布局</h2><p>目录固定在正文左侧，当前条目有清晰的选中状态。正文使用适合长文的行高与宽度；手机端将目录收进选择器。</p><h2>来源与快照</h2><p>正文与当前快照绑定。来源入口集中展示分支、提交和更新时间，不重复出现在每一段内容中。</p><div class="info-note">${I('BookOpen')}<span>阅读体验优先：保留已显示的内容，并将刷新与异常反馈放在合适的位置。</span></div><h2>相关材料</h2><p>Change 详情通过抽屉打开，查阅任务与方案后可以回到原来的阅读位置。</p>`,
 previews:`<p class="lead">原型将方案转换为可操作的界面，帮助团队在进入正式实现前对齐体验。</p><h2>固定版本</h2><p>每个交付入口关联固定的源码与产物版本。历史 Change 的原型引用不会跟随当前页面变化。</p><h2>设备预览</h2><p>在桌面、iPad 和手机之间切换，检查内容重排和主要操作。缩略图与入口保持在同一版本。</p><div class="info-note">${I('PanelsTopLeft')}<span>原型使用示例数据运行。这里的交互不会更改真实项目、账号或工程记录。</span></div>`,
 theme:`<p class="lead">统一的基础组件与语义颜色，让每个模块有一致的操作感，同时为阅读保留安静的背景。</p><h2>克制的液态玻璃</h2><p>半透明、背景模糊与细腻高光用于导航、项目切换器和浮层。正文、表格和输入区域保持稳定、不透明，确保信息清晰。</p><h2>蓝色的层级</h2><p>蓝色用于主操作、当前选中与重点链接。背景使用低饱和雾蓝，状态色只表达实际意义，并搭配文案。</p><h2>明暗主题</h2><p>浅色适合日间阅读；深色使用深蓝灰表面和更柔和的蓝色强调。两个主题都保留可见键盘焦点与减弱动态效果的偏好。</p>`,
 runtime:`<p class="lead">将源码、构建与实际运行版本区分清楚，让开发验证有可靠依据。</p><h2>开发与验证</h2><p>主工作区使用协作分支构建长期服务。任务工作区用于独立验证，构建产物可以重建，不保存用户数据。</p><h2>服务更新</h2><p>更新前确认待部署内容已经集成并验证，再依次停止、构建、启动与检查。生产构建使用同一个输出目录，避免覆盖运行中的产物。</p><div class="info-note">${I('Info')}<span>当前页面是独立交互原型，不会启动、停止或更改实际服务。</span></div>`
};
function specs(){const doc=documents.find(d=>d.id===state.doc)||documents[0],repo=currentRepo();return `${heading('Specs','项目当前的能力与约定。',repoSelect())}<select class="mobile-doc-picker" data-doc-select aria-label="选择要阅读的规格">${documents.map(d=>`<option value="${d.id}" ${d.id===doc.id?'selected':''}>${d.title}</option>`).join('')}</select><div class="reading-layout"><nav class="docs-sidebar" aria-label="Specs 目录">${['产品能力','设计与实现'].map(group=>`<p class="nav-label">${group}</p>${documents.filter(d=>d.group===group).map(d=>`<a class="doc-link" href="${href('specs',{repo:repo.id,doc:d.id})}" ${d.id===doc.id?'aria-current="page"':''}>${I('FileText')}<span>${d.title}</span></a>`).join('')}`).join('')}<div class="doc-version">${I('GitBranch')} develop<br>最近更新 · 今天 14:32</div></nav><article class="article"><div class="article-top"><span class="row">${I('BookOpen')}${repo.name}<span> / </span>${doc.group}</span><button class="btn quiet" data-action="share">${I('Link')}复制链接</button></div><h1>${doc.title}</h1>${articleBodies[doc.id]}<div class="article-bottom"><button class="text-button" data-action="source">${I('GitBranch')}查看来源${I('ArrowUpRight')}</button><span>示例文档 · 约 3 分钟阅读</span></div></article></div>`;}
function changePage(){return `${heading('Changes','需求、方案与交付进展，按变更集中阅读。',repoSelect())}<div class="toolbar"><div class="tabs" role="tablist" aria-label="Change 筛选">${[['active','进行中',3],['archived','已归档',3],['all','全部',6]].map(([id,label,n])=>`<button class="tab" role="tab" id="change-filter-${id}" aria-controls="change-results" aria-selected="${state.changeFilter===id}" data-change-filter="${id}">${label}<span class="tab-count">${n}</span></button>`).join('')}</div><div class="toolbar-right"><label class="input-wrap">${I('Search')}<span class="sr-only">搜索变更</span><input id="change-search" type="search" placeholder="搜索变更…" value="${esc(state.changeQuery)}" autocomplete="off"></label></div></div><div class="changes-list" id="change-results" role="tabpanel" aria-labelledby="change-filter-${state.changeFilter}"></div><p class="list-caption">点击变更，查看目标、任务和相关材料。</p>${footer()}`;}
function updateChanges(){const root=$('#change-results');if(!root)return;const list=changes.filter(c=>(state.changeFilter==='all'||(state.changeFilter==='active'?c.active:!c.active))&&(c.name+' '+c.id).toLowerCase().includes(state.changeQuery.toLowerCase()));root.innerHTML=list.length?list.map(c=>`<button class="change-row" data-change="${c.id}" aria-label="查看变更：${c.name}"><span class="change-symbol ${!c.active?'complete':''}">${I(c.active?'GitPullRequest':'Check')}</span><span><h3>${c.name}</h3><p><span class="mono">${c.id}</span><span>·</span><span>${c.tasks} 任务</span></p></span>${badge(c.stage,c.tone,true)}<time>${c.time}</time>${I('ChevronRight')}</button>`).join(''):`<div class="empty">${I('Search')}<h3>没有匹配的变更</h3><p>换一个关键词，或查看全部变更。</p><button class="btn" data-action="reset-changes">显示全部变更</button></div>`;}
const previewData=[{id:'home',title:'蓝色玻璃工作台',description:'仓库发现、搜索与收藏',label:'当前方案',route:'home'},{id:'specs',title:'专注阅读',description:'Specs 目录与文档阅读',label:'交互原型',route:'specs'},{id:'changes',title:'变更与交付',description:'状态筛选与详情抽屉',label:'交互原型',route:'changes'}];
const previewSrc=(id,device=state.device)=>PREVIEWS[id]?.[device]||PREVIEWS[id]?.['pc-web']||'';
function prototypes(){return `${heading('原型','打开方案，看看它实际如何工作。',repoSelect())}<div class="toolbar"><div class="tabs" role="tablist" aria-label="原型设备"><button class="tab" id="preview-tab" role="tab" aria-selected="true" aria-controls="preview-results">全部原型<span class="tab-count">3</span></button></div><div class="device-options" role="group" aria-label="预览设备">${deviceButtons(state.device)}</div></div><div class="prototype-grid" id="preview-results" role="tabpanel" aria-labelledby="preview-tab">${previewData.map((p,i)=>`<article class="preview-card"><div class="preview-image" data-device="${state.device}">${previewSrc(p.id)?`<img src="${previewSrc(p.id)}" alt="${p.title}的实际页面截图">`:`<div class="placeholder">${I(i?'FileText':'LayoutGrid')} ${p.title}</div>`}</div><div class="preview-info"><div class="between"><h3>${p.title}</h3>${badge(p.label,i?'neutral':'')}</div><p>${p.description}</p><div class="preview-grid-footer"><span class="muted small">${I('Clock3')} 今天 14:32</span><button class="btn" data-preview="${p.id}">打开原型${I('ArrowUpRight')}</button></div></div></article>`).join('')}</div>${footer()}`;}
function deviceButtons(value){return [['pc-web','Monitor','桌面'],['ipad','Tablet','iPad'],['mobile','Smartphone','手机']].map(([id,icon,label])=>`<button data-device="${id}" aria-label="${label}预览" aria-pressed="${value===id}">${I(icon)}</button>`).join('');}
function settings(){return `${heading('偏好设置','让工作台更适合你的阅读习惯。')}<section class="settings-section"><h2>外观</h2><p>以清晰的正文和轻盈的导航，保持阅读专注。</p><div class="settings-row"><div><h3>界面主题</h3><p>切换工作台的明暗外观。</p></div><div class="theme-options" role="group" aria-label="界面主题"><button class="btn" data-set-theme="light" aria-pressed="${state.theme==='light'}">${I('Sun')}浅色</button><button class="btn" data-set-theme="dark" aria-pressed="${state.theme==='dark'}">${I('Moon')}深色</button></div></div></section><section class="settings-section"><h2>当前身份</h2><p>身份信息与仓库访问在这里集中管理。</p><div class="account-line">${I('Github')}<span class="stack"><strong>Demo 工作台</strong><span class="muted small">demo-user · GitHub</span></span>${badge('示例身份','green',true)}</div><div class="settings-row"><div><h3>设备与会话</h3><p>此浏览器 · 仅在原型内演示</p></div>${button('查看身份','account','KeyRound')}</div></section><p class="muted small">所有操作仅作用于示例数据，刷新页面后恢复初始状态。</p>`;}
function openDialog(id,content){const dialog=$(id);dialog.innerHTML=content;if(!dialog.open)dialog.showModal();return dialog;}
function closeDialogs(){for(const d of $$('dialog[open]'))d.close();}
function openModal(title,body,actions=''){return openDialog('#modal',`<div class="between"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-close="modal" aria-label="关闭">${I('X')}</button></div>${body}${actions?`<div class="modal-actions">${actions}</div>`:''}`);}
function openSearch(){openDialog('#command',`<h2 id="command-title" class="sr-only">搜索工作台</h2><label class="command-input">${I('Search')}<span class="sr-only">搜索项目、规格与变更</span><input id="command-query" placeholder="搜索项目、规格与变更…" autocomplete="off"><kbd>ESC</kbd></label><div class="command-results" id="command-results"></div><div class="command-footer">Tab 选择结果 · Enter 打开 · Esc 关闭</div>`);updateSearch('');$('#command-query').focus();}
function updateSearch(query){const rows=[...repos.filter(r=>r.ready).map(r=>({title:r.name,kind:'仓库',icon:'FolderGit2',link:href('specs',{repo:r.id})})),...documents.map(d=>({title:d.title,kind:'Specs',icon:'FileText',link:href('specs',{doc:d.id})})),...changes.filter(c=>c.active).map(c=>({title:c.name,kind:'Change',icon:'GitPullRequest',change:c.id,link:'#/changes'})),{title:'原型总览',kind:'原型',icon:'PanelsTopLeft',link:'#/prototypes'}].filter(r=>r.title.toLowerCase().includes(query.toLowerCase()));$('#command-results').innerHTML=rows.length?rows.map(r=>`<a href="${r.link}" ${r.change?`data-open-change="${r.change}"`:''}>${I(r.icon)}${esc(r.title)}<small>${r.kind}</small></a>`).join(''):'<p class="muted small" style="padding:20px">没有匹配结果，试试“仓库”“阅读”或“原型”。</p>';}
function showChange(id,tab='overview'){const c=changes.find(c=>c.id===id)||changes[0];state.detailChange=c.id;state.detailTab=tab;let body='';if(tab==='overview')body=`<h3>这次变更解决什么</h3><p>${c.description}</p><dl class="detail-meta"><dt>当前阶段</dt><dd>${badge(c.stage,c.tone,true)}</dd><dt>任务进展</dt><dd>${c.tasks} 项完成</dd><dt>工作分支</dt><dd class="mono">${c.branch}</dd><dt>更新于</dt><dd>${c.time}</dd></dl><h3>交付要点</h3><ul><li>保留项目上下文，让入口与阅读位置更清晰。</li><li>主要操作直接可达，来源信息按需查看。</li><li>覆盖桌面、平板与手机的实际使用场景。</li></ul><div class="info-note">${I('Info')}<span>此处为原型示例记录，任务与状态不会写入真实仓库。</span></div>`;if(tab==='tasks'){const n=Number(c.tasks.split('/')[0]);body=['梳理页面结构与信息层级','完成主要路径的交互原型','验证明暗主题与响应式布局','检查键盘操作和异常反馈'].map((t,i)=>`<div class="task ${i<n?'':'pending'}">${I(i<n?'CheckCircle2':'Circle')}<div><strong>T${i+1} · ${t}</strong><div class="muted">${i<n?'已完成 · 已保留验证证据':i===n?'进行中':'尚未开始'}</div></div></div>`).join('');}if(tab==='materials')body=`<h3>相关材料</h3><div class="stack"><a class="doc-link" href="${href('specs',{doc:'overview'})}">${I('FileText')}需求与方案要点${I('ArrowUpRight')}</a><a class="doc-link" href="#/prototypes">${I('PanelsTopLeft')}交互原型${I('ArrowUpRight')}</a><a class="doc-link" href="${href('specs',{doc:'theme'})}">${I('BookOpen')}共享组件与主题${I('ArrowUpRight')}</a></div>`;
 openDialog('#detail',`<header class="detail-head"><div class="between"><span class="row muted small">${I('GitPullRequest')}Change 详情</span><div class="row"><button class="icon-btn" data-action="share-change" aria-label="复制此变更的链接">${I('Link')}</button><button class="icon-btn" data-close="detail" aria-label="关闭详情">${I('X')}</button></div></div><h2 id="detail-title">${c.name}</h2><p class="mono">${c.id}</p></header><div class="detail-tabs" role="tablist" aria-label="变更详情">${[['overview','概览'],['tasks','任务'],['materials','材料']].map(([key,label])=>`<button class="tab" id="detail-tab-${key}" role="tab" aria-controls="detail-panel" aria-selected="${tab===key}" data-detail-tab="${key}">${label}${key==='tasks'?`<span class="tab-count">${c.tasks}</span>`:''}</button>`).join('')}</div><div class="detail-body" id="detail-panel" role="tabpanel" aria-labelledby="detail-tab-${tab}">${body}</div>`);}
function showSource(){openModal('记录来源',`<p>来源信息集中在这里，正文保持简洁。</p><div class="source-details"><p><strong>仓库</strong><br><code>demo-user / ${currentRepo().id}</code></p><p><strong>读取分支</strong><br><code>develop</code></p><p><strong>快照</strong><br><code>a7e2c91</code> · 今天 14:32</p><p class="muted">以上为示例来源，原型不读取真实工程数据。</p></div>`,button('知道了','close-modal','','primary'));}
function addRepo(){openModal('检查仓库',`<p>已有仓库会自动发现。未出现在列表中时，可以用仓库地址补充检查。</p><div id="repo-form"><label for="repo-url">GitHub 仓库地址</label><input id="repo-url" placeholder="https://github.com/demo-team/docs-kit" autocomplete="off" required><div class="muted small" style="margin-top:9px">原型仅检查示例地址，不发起网络请求。</div><div id="repo-error" class="modal-error" role="alert"></div><div class="modal-actions"><button class="btn" type="button" data-close="modal">取消</button><button class="btn primary" type="button" data-action="check-repo">检查仓库${I('ArrowRight')}</button></div></div>`);}
function showAccount(){openModal('当前身份',`<div class="account-line" style="margin-top:20px">${I('Github')}<span class="stack"><strong>Demo 工作台</strong><span class="small muted">demo-user · GitHub</span></span>${badge('当前','green',true)}</div><p>使用示例身份浏览仓库、规格与原型。所有操作在当前页面内演示，不录入真实凭据。</p>`,button('偏好设置','open-settings','Settings2')+button('知道了','close-modal','','primary'));}
function pickRepo(){openModal('切换项目',`<p>选择项目，继续当前模块的阅读。</p>${repos.filter(r=>r.ready).map(r=>`<button class="repo-picker-item" data-pick-repo="${r.id}">${mark(r)}<span class="stack"><strong>${r.name}</strong><span class="small muted">${r.path}</span></span>${r.id===state.repo?I('Check'):''}</button>`).join('')}`);}
async function copyLink(change=false){const link=location.href.split('#')[0]+(change?'#/changes?change='+state.detailChange:location.hash||'#/home');try{if(!navigator.clipboard||(document.permissionsPolicy||document.featurePolicy)?.allowsFeature('clipboard-write')===false)throw Error('Clipboard unavailable');await navigator.clipboard.writeText(link);toast('已复制阅读链接');}catch{openModal('复制阅读链接',`<p>浏览器未授予剪贴板权限，可选中下方内容手动复制。</p><label for="copy-link">原型阅读位置</label><textarea id="copy-link" readonly>${esc(link)}</textarea>`,button('完成','close-modal','','primary'));$('#copy-link').select();}}
function preview(id){const p=previewData.find(p=>p.id===id);if(!p)return;state.preview=id;const modal=$('#modal');modal.classList.add('preview-full-dialog');openDialog('#modal',`<header><h2 id="modal-title">${p.title}</h2><div class="row"><div class="device-options" role="group" aria-label="预览设备">${deviceButtons(state.device)}</div><button class="btn primary" data-action="enter-preview">进入交互${I('ArrowUpRight')}</button><button class="icon-btn" data-close="modal" aria-label="关闭原型">${I('X')}</button></div></header><div class="preview-frame-wrap"><img id="preview-full-image" src="${previewSrc(p.id)}" alt="${p.title}的${state.device==='mobile'?'手机':state.device==='ipad'?'iPad':'桌面'}实际页面截图" data-preview-device="${state.device}"></div>`);}
async function refresh(){if(state.refreshing)return;state.refreshing=true;render();await new Promise(r=>setTimeout(r,700));state.refreshing=false;state.lastUpdated='刚刚';render();toast('仓库与工程记录已更新 · 示例操作');}
function setTheme(theme){state.theme=theme;render();toast(theme==='light'?'已切换为浅色主题':'已切换为深色主题');}
function checkRepo(){const value=$('#repo-url').value.trim();if(!/^https:\/\/github\.com\/(demo-user|demo-team)\/[a-z0-9-]+\/?$/i.test(value)){$('#repo-error').textContent='请使用示例地址，例如 https://github.com/demo-team/docs-kit';$('#repo-url').setAttribute('aria-invalid','true');return;}closeDialogs();toast('示例仓库已检查，可在“需关注”中查看接入状态');state.filter='attention';state.query='';go('home');}
const actions={'check-repo':checkRepo,'enter-preview':()=>{const p=previewData.find(p=>p.id===state.preview);closeDialogs();if(p)go(p.route);},search:openSearch,theme:()=>setTheme(state.theme==='light'?'dark':'light'),refresh,account:showAccount,'pick-repo':pickRepo,'add-repo':addRepo,source:showSource,share:()=>copyLink(), 'share-change':()=>copyLink(true), 'close-modal':()=>$('#modal').close(),'open-settings':()=>{closeDialogs();go('settings');},'reset-filter':()=>{state.filter='all';state.query='';render();},'reset-changes':()=>{state.changeFilter='all';state.changeQuery='';render();},setup:()=>openModal('接入 SpecTrail',`<p>Docs Kit 已被发现，但还没有有效的 SpecTrail 项目配置。</p><div class="source-details"><p><strong>下一步</strong><br>在仓库中完成 SpecTrail Setup，将项目配置推送到协作分支，然后返回工作台重新检查。</p><p class="muted">原型不会创建或修改真实仓库文件。</p></div>`,button('重新检查','demo-recheck','RefreshCw','primary')),'demo-recheck':()=>{closeDialogs();toast('示例检查完成：仍需先在仓库完成 Setup');},help:()=>openModal('从这里开始',`<p><strong>我的仓库</strong>是项目入口。使用星标收藏常用项目，点击项目进入 Specs。</p><p><strong>Specs</strong>阅读当前能力与约定；<strong>Changes</strong>跟进正在推进的变更；<strong>原型</strong>查看可操作的方案。</p><p>按 <kbd>⌘ K</kbd> 或 <kbd>Ctrl K</kbd> 打开全局搜索，按 <kbd>Esc</kbd> 关闭浮层。</p>`,button('开始浏览','close-modal','','primary'))};
document.addEventListener('click',event=>{
 const close=event.target.closest('[data-close]');if(close){$('#'+close.dataset.close).close();return;}
 const change=event.target.closest('[data-change],[data-open-change]');if(change){event.preventDefault();$('#command').close();showChange(change.dataset.change||change.dataset.openChange);return;}
 const action=event.target.closest('[data-action]');if(action){event.preventDefault();actions[action.dataset.action]?.();return;}
 const star=event.target.closest('[data-star]');if(star){const r=repos.find(r=>r.id===star.dataset.star);r.favorite=!r.favorite;render();toast(r.favorite?'已加入收藏':'已取消收藏');return;}
 const filter=event.target.closest('[data-filter]');if(filter){state.filter=filter.dataset.filter;render();return;}
 const changeFilter=event.target.closest('[data-change-filter]');if(changeFilter){state.changeFilter=changeFilter.dataset.changeFilter;render();return;}
 const view=event.target.closest('[data-view]');if(view){state.view=view.dataset.view;render();return;}
 const theme=event.target.closest('[data-set-theme]');if(theme){setTheme(theme.dataset.setTheme);return;}
 const picked=event.target.closest('[data-pick-repo]');if(picked){state.repo=picked.dataset.pickRepo;closeDialogs();go(['home','settings'].includes(route())?'specs':route(),{repo:state.repo});return;}
 const tab=event.target.closest('[data-detail-tab]');if(tab){showChange(state.detailChange,tab.dataset.detailTab);return;}
 const device=event.target.closest('[data-device]');if(device&&device.tagName==='BUTTON'){state.device=device.dataset.device;const frame=$('#preview-full-image');if(frame&&$('#modal').open){frame.dataset.previewDevice=state.device;frame.src=previewSrc(state.preview);frame.alt='实际页面截图 · '+state.device;$$('#modal [data-device]').filter(b=>b.tagName==='BUTTON').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.device===state.device)));}else render();return;}
 const p=event.target.closest('[data-preview]');if(p){preview(p.dataset.preview);return;}
 const link=event.target.closest('a[href^="#/"]');if(link)closeDialogs();
});
document.addEventListener('input',event=>{if(event.target.id==='repo-search'){state.query=event.target.value;updateCards();}if(event.target.id==='change-search'){state.changeQuery=event.target.value;updateChanges();}if(event.target.id==='command-query')updateSearch(event.target.value);});
document.addEventListener('change',event=>{if(event.target.matches('[data-repo-select]')){state.repo=event.target.value;go(route(),{repo:state.repo});}if(event.target.matches('[data-doc-select]'))go('specs',{repo:state.repo,doc:event.target.value});});
document.addEventListener('keydown',event=>{if(event.key==='Enter'&&event.target.id==='repo-url'){event.preventDefault();checkRepo();return;}if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();if($('#command').open)$('#command').close();else{closeDialogs();openSearch();}}});
for(const d of $$('dialog')){d.removeAttribute('open');d.addEventListener('click',event=>{if(event.target===d){const r=d.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)d.close();}});d.addEventListener('close',()=>{if(d.id==='modal')d.classList.remove('preview-full-dialog');});}
window.addEventListener('hashchange',()=>{closeDialogs();render();window.scrollTo(0,0);});
render();
const initialChange=new URLSearchParams(location.hash.split('?')[1]||'').get('change');if(initialChange&&changes.some(c=>c.id===initialChange))showChange(initialChange);
})();
